 const cur=await db.query("SELECT * FROM knowledge_documents WHERE id=$1 AND organization_id=$2",[q.params.id,q.actor.organization_id]);if(!cur.rowCount)return r.status(404).json({error:"Document not found."});const v={...cur.rows[0],...body};
